import { Component, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { SafeUrl } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { IonContent, ModalController, ToastController, LoadingController, IonRouterOutlet, MenuController } from '@ionic/angular';
import { Subscription } from 'rxjs';
import { IProductFilterModel, ProductFilterModel } from '../../../../data/model/product/ProductFilterModel';
import { ProductService } from '../../../../data/service/product/product.service';
import { G } from '../../../../core/common/G';
import { GAccount } from '../../../../core/common/GAccount';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { GResponse } from '../../../../core/common/GResponse';
import { ProductFilterComponent } from '../../../components/modal/filter/product-filter/product-filter.component';
import { SiteLanguageService } from '../../../../core/i18n/site-language.service';

export interface IQuickTopic {
  title: string;
  query: string;
  icon?: string;
}

export interface ISortOption {
  id: number;
  label: string;
  icon?: string;
}

@Component({
  selector: 'app-psearch',
  templateUrl: './psearch.component.html',
  styleUrls: ['./psearch.component.scss']
})
export class PSearchComponent implements OnInit, OnDestroy {

  @ViewChild(IonContent) content: IonContent;

  showSearchbar = true;
  filteredProducts: IProductFilterModel;
  queryText = '';
  notfound = false;
  isLoading = false;

  courseCount = 0;
  productCount = 0;
  private subscriptions = new Subscription();

  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';

  quickTopics: IQuickTopic[] = [
    { title: 'همه کاربرگ‌ها', query: '', icon: 'cube-outline' },
    { title: 'کاربرگ پایه اول', query: 'پایه اول', icon: 'school-outline' },
    { title: 'کاربرگ فارسی و نشانه‌ها', query: 'فارسی', icon: 'book-outline' },
    { title: 'ریاضی و تم‌های اول', query: 'ریاضی', icon: 'calculator-outline' },
    { title: 'پیک آدینه و آزمون هفتگی', query: 'پیک آدینه', icon: 'document-text-outline' },
    { title: 'طرح درس سالانه و روزانه', query: 'طرح درس', icon: 'reader-outline' },
    { title: 'پیش‌دبستانی و دست‌ورزی', query: 'پیش دبستانی', icon: 'happy-outline' },
    { title: 'آزمون‌های ماهانه', query: 'آزمون', icon: 'ribbon-outline' }
  ];

  sortOptions: ISortOption[] = [
    { id: 4, label: 'جدیدترین', icon: 'sparkles-outline' },
    { id: 3, label: 'پربازدیدترین', icon: 'flame-outline' },
    { id: 1, label: 'ارزان‌ترین', icon: 'arrow-down-circle-outline' },
    { id: 2, label: 'گران‌ترین', icon: 'arrow-up-circle-outline' }
  ];

  constructor(
    private activatedRoute: ActivatedRoute,
    private productService: ProductService,
    private router: Router,
    public modalCtrl: ModalController,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public routerOutlet: IonRouterOutlet,
    public language: SiteLanguageService,
    private menuCtrl: MenuController
  ) { }

  get loggedIn(): boolean {
    return GAccount.IsLoggedIn();
  }

  get cartCount(): number {
    return this.courseCount + this.productCount;
  }

  get currentSortId(): number {
    if (!this.filteredProducts || this.filteredProducts.sortId == null) {
      return 4;
    }
    return +this.filteredProducts.sortId;
  }

  get hasActiveFilters(): boolean {
    if (!this.filteredProducts) {
      return !!(this.queryText && this.queryText.trim().length > 0);
    }
    const hasQuery = !!(this.queryText && this.queryText.trim().length > 0);
    const hasStartPrice = this.filteredProducts.startPrice != null && +this.filteredProducts.startPrice > 0;
    const hasEndPrice = this.filteredProducts.endPrice != null && +this.filteredProducts.endPrice > 0;
    const hasCats = !!(this.filteredProducts.categoryIds && this.filteredProducts.categoryIds.length > 0);
    const hasNonDefaultSort = this.filteredProducts.sortId != null && +this.filteredProducts.sortId !== 4 && +this.filteredProducts.sortId !== 0;
    const hasFlags = this.filteredProducts.onlyUsed || this.filteredProducts.onlyExisting;

    return hasQuery || hasStartPrice || hasEndPrice || hasCats || hasNonDefaultSort || hasFlags;
  }

  url(path: string): string {
    return this.language.url(path);
  }

  async toggleAppMenu(): Promise<void> {
    await this.menuCtrl.toggle();
  }

  goTop() {
    if (this.content) {
      this.content.scrollToTop(600);
    }
  }

  doRefresh(event: any) {
    setTimeout(() => {
      location.reload();
      event?.target?.complete();
    }, 1500);
  }

  ngOnInit(): void {
    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;

    this.subscriptions.add(
      GResponse.getCartCoursesCount().subscribe(count => this.courseCount = count)
    );
    this.subscriptions.add(
      GResponse.getCartProductsCount().subscribe(count => this.productCount = count)
    );

    let filter: IProductFilterModel;

    this.subscriptions.add(
      this.activatedRoute.queryParams.subscribe(params => {
        const page = params.page ? +params.page : 1;
        const take = params.take ? +params.take : 12;
        const title = params.title ? params.title : '';
        const startPrice = params.startPrice ? +params.startPrice : null;
        const endPrice = params.endPrice ? +params.endPrice : null;
        const categoryIds = params.categoryIds ? params.categoryIds : null;
        const sortId = params.sortId ? +params.sortId : 4;
        let isUsed = params.isUsed ? params.isUsed == 'true' : false;
        let onlyUsed = params.onlyUsed ? params.onlyUsed == 'true' : false;
        const onlyExisting = params.onlyExisting ? params.onlyExisting == 'true' : false;

        this.queryText = title;

        if (
          startPrice == null &&
          endPrice == null &&
          categoryIds == null &&
          sortId == 4 &&
          !isUsed &&
          !onlyUsed &&
          !onlyExisting
        ) {
          filter = new ProductFilterModel(false, page, take, title);
        } else {
          const catIds: number[] = [];

          if (categoryIds != null) {
            if (typeof categoryIds === 'string' && categoryIds.length > 0) {
              if (categoryIds.includes(',')) {
                categoryIds.split(',').forEach(cat => catIds.push(+cat));
              } else {
                catIds.push(+categoryIds);
              }
            } else if (Array.isArray(categoryIds)) {
              categoryIds.forEach(cat => catIds.push(+cat));
            }
          }

          if ((isUsed && onlyUsed) || (!isUsed && !onlyUsed)) {
            isUsed = false;
            onlyUsed = false;
          } else if (isUsed || onlyUsed) {
            isUsed = true;
          }

          filter = new ProductFilterModel(
            true,
            page,
            take,
            title,
            startPrice,
            endPrice,
            onlyUsed,
            onlyExisting,
            catIds,
            sortId,
            isUsed
          );
        }

        this.filteredProducts = filter;
        this.isLoading = true;

        SharedIonic.loading(this.loadingController);

        this.productService.GetProductsByFilter(filter).subscribe(
          res => {
            this.isLoading = false;
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredProducts = res.data;
              this.notfound = false;
            } else if (res.status === GResponse.NotFoundStatus) {
              this.notfound = true;
              SharedIonic.toast(this.toastController, this.language.text('search.noResults'));
            }
          },
          err => {
            this.isLoading = false;
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
          }
        );
      })
    );
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  async presentFilter() {
    const modal = await this.modalCtrl.create({
      component: ProductFilterComponent,
      swipeToClose: true,
      presentingElement: this.routerOutlet.nativeEl,
      componentProps: { filteredProducts: this.filteredProducts }
    });
    await modal.present();

    const { data } = await modal.onWillDismiss();
    if (data) {
      this.filteredProducts = data;
      this.setQueryParams(1);
    }
  }

  setQueryParams(pageId: number) {
    this.goTop();

    this.router.navigate(
      ['Product', 'Search'],
      {
        queryParams: {
          page: pageId < 1 ? 1 : pageId,
          take: this.filteredProducts?.takeEntity ? this.filteredProducts.takeEntity : null,
          title: this.filteredProducts?.title ? this.filteredProducts.title : null,
          startPrice: this.filteredProducts?.startPrice ? this.filteredProducts.startPrice : null,
          endPrice: this.filteredProducts?.endPrice ? this.filteredProducts.endPrice : null,
          categoryIds: this.filteredProducts?.categoryIds && this.filteredProducts.categoryIds.length > 0
            ? this.filteredProducts.categoryIds.join(',')
            : null,
          sortId: this.filteredProducts?.sortId != null ? this.filteredProducts.sortId : 4,
          onlyUsed: this.filteredProducts?.onlyUsed ? this.filteredProducts.onlyUsed : null,
          onlyExisting: this.filteredProducts?.onlyExisting ? this.filteredProducts.onlyExisting : null,
          isUsed: this.filteredProducts?.isUsed ? this.filteredProducts.isUsed : null
        }
      }
    );
  }

  search() {
    if (this.filteredProducts) {
      this.filteredProducts.title = this.queryText ? this.queryText.trim() : '';
    }
    this.setQueryParams(1);
  }

  clearSearch() {
    this.queryText = '';
    if (this.filteredProducts) {
      this.filteredProducts.title = '';
      this.filteredProducts.startPrice = null;
      this.filteredProducts.endPrice = null;
      this.filteredProducts.categoryIds = [];
      this.filteredProducts.sortId = 4;
      this.filteredProducts.onlyUsed = false;
      this.filteredProducts.onlyExisting = false;
    }
    this.setQueryParams(1);
  }

  quickSearch(term: string) {
    this.queryText = term;
    if (this.filteredProducts) {
      this.filteredProducts.title = term;
    }
    this.setQueryParams(1);
  }

  isTopicActive(term: string): boolean {
    if (!term || term === '') {
      return !this.queryText || this.queryText.trim().length === 0;
    }
    return (this.queryText || '').trim().toLowerCase() === term.trim().toLowerCase();
  }

  setSort(sortId: number) {
    if (this.filteredProducts) {
      this.filteredProducts.sortId = sortId;
      this.setQueryParams(1);
    }
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {
    const array: string[] = [];
    const count = +pageCount;
    for (let i = 1; i <= count; i++) {
      array.push(i.toString());
    }
    return array;
  }

  goPreviousPage() {
    if (!this.filteredProducts?.startPage) { return; }
    if (this.filteredProducts.pageId > this.filteredProducts.startPage && +this.filteredProducts.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredProducts.pageId - 1);
    }
  }

  goNextPage() {
    if (!this.filteredProducts?.endPage) { return; }
    if (this.filteredProducts.pageId < this.filteredProducts.endPage) {
      this.setQueryParams(+this.filteredProducts.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  onSort(sortId: any) {
    const val = sortId?.detail?.value != null ? +sortId.detail.value : 4;
    this.setSort(val);
  }
}
